    return (
      <aside className="sticky top-24 hidden h-[calc(100vh-7rem)] w-[300px] shrink-0 space-y-md self-start overflow-y-auto rounded-xl border border-white/10 bg-white/5 p-sm backdrop-blur-md lg:block premium-glass">
