export const useSearchStore = create<SearchState>((set, get) => ({
  // ─────────────────────────────────────────────────────────────────────────
  // Ticket tracking
  // ─────────────────────────────────────────────────────────────────────────
  trackedTicket: null,
  trackError: null,
  trackLoading: false,

  lookupTicket: async (pnr: string, lastName: string) => {
    set({ trackLoading: true, trackError: null });

    // Simulate network latency
    await new Promise((resolve) => setTimeout(resolve, 600));

    const key = `${pnr.toUpperCase()}:${lastName.toLowerCase()}`;
    const ticket = MOCK_TICKETS[key];

    if (ticket) {
      set({ trackedTicket: ticket, trackError: null, trackLoading: false });
      return true;
    }

    set({
      trackError: 'No active reservation found matching those credentials. Please verify your PNR and last name.',
      trackedTicket: null,
      trackLoading: false,
    });
    return false;
  },

  clearTrackedTicket: () => set({ trackedTicket: null, trackError: null, trackLoading: false }),

  // ─────────────────────────────────────────────────────────────────────────
  // Search state
  // ─────────────────────────────────────────────────────────────────────────
  searchParams: defaultParams,
  recentSearches: [],
  isSearching: false,
  lastSearchTimestamp: null,

  setSearchParams: (patch) => {
    set({ searchParams: { ...get().searchParams, ...patch } });
  },

  addRecentSearch: (s) => {
    set((state) => ({ recentSearches: [s].concat(state.recentSearches).slice(0, 8) }));
  },

  reset: () => {
    set({ searchParams: defaultParams, isSearching: false });
  },

  // UI convenience bindings — mirror searchParams.from/to
  origin: defaultParams.from,
  destination: defaultParams.to,

  setOrigin: (code: string) => {
    set((state) => ({
      searchParams: { ...state.searchParams, from: code },
      origin: code,
    }));
  },

  setDestination: (code: string) => {
    set((state) => ({
      searchParams: { ...state.searchParams, to: code },
      destination: code,
    }));
  },

  executeSearch: async () => {
    set({ isSearching: true, lastSearchTimestamp: new Date().toISOString() });
    // The query is triggered reactively by React Query (useFlightsQuery) when searchParams changes.
    // Navigation is handled inside the submitting form using standard React Router hooks.
    await Promise.resolve();
    set({ isSearching: false });
  },
}));

export default useSearchStore;

import { AIRPORTS } from '../data/airports';

export interface RouteAnalysis {
  distanceKm: number;
  distanceMiles: number;
  flightTimeHours: number;
  flightTimeFormatted: string;
  stops: number;
  stopAnalysis: string;
  typicalAircraft: string;
  commonHubs: string[];
}

function deg2rad(deg: number): number {
  return deg * (Math.PI / 180);
}

// Haversine formula
export function calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371; // Earth radius in km
  const dLat = deg2rad(lat2 - lat1);
  const dLon = deg2rad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

export function analyzeRoute(originIata: string, destIata: string): RouteAnalysis | null {
  const origin = AIRPORTS[originIata];
  const dest = AIRPORTS[destIata];

  if (!origin || !dest) return null;

  const distanceKm = Math.round(calculateDistance(origin.lat, origin.lon, dest.lat, dest.lon));
  const distanceMiles = Math.round(distanceKm * 0.621371);

  // Average cruising speed 900km/h + 45 mins for takeoff/landing
  let totalHours = (distanceKm / 900) + 0.75;
  const hours = Math.floor(totalHours);
  const minutes = Math.round((totalHours - hours) * 60);

  let stops = 0;
  let stopAnalysis = '';
  let typicalAircraft = 'Airbus A320 / Boeing 737';
  let commonHubs: string[] = [];

  if (distanceKm < 3000) {
    stops = 0;
    stopAnalysis = 'Non-stop route. Operates daily direct.';
  } else if (distanceKm < 8500) {
    stops = 0;
    stopAnalysis = 'Typically non-stop. Long-haul direct route.';
    typicalAircraft = 'Boeing 787 / Airbus A350';
  } else if (distanceKm < 14000) {
    stops = 0; // Ultra long haul, but often non-stop nowadays
    stopAnalysis = 'Ultra-long-haul. Often non-stop, but may require 1 stop depending on carrier.';
    typicalAircraft = 'Airbus A350-1000 / Boeing 777-300ER';
    commonHubs = ['DXB', 'DOH', 'FRA'];
  } else {
    stops = 1;
    stopAnalysis = '1 Stop required. Exceeds typical commercial range.';
    typicalAircraft = 'Airbus A380 / Boeing 777-300ER';
    commonHubs = ['DXB', 'SIN', 'LHR', 'DOH'];
    // Add layover time
    totalHours += 2.5;
  }

  return {
    distanceKm,
    distanceMiles,
    flightTimeHours: totalHours,
    flightTimeFormatted: `${hours}h ${minutes}m`,
    stops,
    stopAnalysis,
    typicalAircraft,
    commonHubs
  };
}
